impl<T: gx::Real> Point<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[2] * x[2];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (7 mul, 0 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Point<(), T> {
        let x = self.c;
        let t0 = x[2] * x[2];
        let t1 = x[2] * t0;
        let t2 = x[2] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = -t5;
        let t9 = -t6;
        let t10 = -t7;
        Point::from_coeffs([t8, t9, t10])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[2] * x[2];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        gx::Unit::new_unchecked(Point::from_coeffs([t0, t1, t2]))
    }

    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Motor<(), T>> {
        let x = self.c;
        let p0 = x[2] * x[2];
        let p1 = -p0;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs(-1, p1, T::from_i64(0));
        let t0 = x[2] * s0;
        let t1 = x[0] * s0;
        let t2 = x[1] * s0;
        gx::Unit::new_unchecked(Motor::from_coeffs([c0, t0, t1, t2]))
    }

}

#[doc = "The pseudoscalar `e012`."]
///
/// Blades, in coefficient order: `[e012]`.
///
/// `S` lists the open slots: `Pseudoscalar` (that is, `Pseudoscalar<()>`) is a value, `Pseudoscalar<(A,)>` a
/// linear map from `A`, `Pseudoscalar<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Pseudoscalar<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 1],
}

