impl<T: gx::Real> Multivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[2] * x[2];
        let t2 = x[3] * x[3];
        let t3 = x[6] * x[6];
        let t4 = t0 + t1;
        let t5 = t2 + t4;
        let t6 = t3 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

impl<S1: gx::Slots, S2: gx::Slots, T: gx::Coef> gx::Gp<Scalar<S2, T>> for Scalar<S1, T> {
    type Output = Scalar<gx::Cat<S1, S2>, T>;
    #[inline]
    fn gp(self, rhs: Scalar<S2, T>) -> Scalar<gx::Cat<S1, S2>, T> {
        let a = self.c.map(gx::SlotArr::<S1, T>);
        let b = rhs.c.map(gx::SlotArr::<S2, T>);
        Scalar {
            c: [
                (a[0] * b[0]).0,
            ],
        }
    }
}

